    'legal.termsContent1': '1. Платформа BOLH выступает посредником между заказчиком и исполнителем. Платформа не является стороной трудового договора.',
    'legal.termsContent2': '2. Исполнитель несёт полную ответственность за качество оказываемых услуг. Платформа не отвечает за действия или бездействие исполнителя.',
    'legal.termsContent3': '3. Комиссия платформы является невозвратной и покрывает расходы на обеспечение работы сервиса, поиск специалистов и техническую поддержку.',
    'legal.termsContent4': '4. Все споры решаются в соответствии с законодательством страны пользователя. Платформа обязуется содействовать разрешению конфликтов.',
    'legal.privacyTitle': 'Политика конфиденциальности',
    'legal.privacyContent1': '1. Мы собираем минимум необходимых данных: имя, телефон, адрес оказания услуг, геолокацию для поиска специалистов.',
    'legal.privacyContent2': '2. Данные хранятся в зашифрованном виде (AES-256) и не передаются третьим лицам без вашего согласия, за исключением случаев, предусмотренных законом.',
    'legal.privacyContent3': '3. Вы имеете право запросить удаление всех персональных данных в любое время через раздел Безопасность в профиле.',
    'legal.cancelTitle': 'Условия отмены и возврата',
    'legal.cancelContent1': '1. Срочный контракт: бесплатная отмена до прибытия специалиста. После прибытия — возврат 50% от стоимости услуги.',
    'legal.cancelContent2': '2. Краткосрочный/месячный контракт: бесплатная отмена за 24 часа до начала. При поздней отмене — удержание до 25%.',
    'legal.cancelContent3': '3. Подписка: отмена в любое время. Оплата действует до конца текущего оплаченного периода.',
    'legal.escrowNote': '💰 Средства хранятся на эскроу-счёте и переводятся исполнителю только после подтверждения выполнения заказа.',
    'legal.liability': 'Платформа BOLH несёт ответственность исключительно в пределах комиссии платформы. За нарушение условий контракта между заказчиком и исполнителем платформа ответственности не несёт.',
    'legal.dispute': 'В случае спора вы можете подать жалобу в течение 14 дней после завершения контракта. Споры рассматриваются в течение 30 рабочих дней.',
