    'legal.termsContent1': '1. BOLH منصة وسيطة بين العملاء ومقدمي الخدمات. المنصة ليست طرفاً في عقد العمل.',
    'legal.termsContent2': '2. يتحمل مقدم الخدمة المسؤولية الكاملة عن جودة الخدمات. المنصة غير مسؤولة عن أفعال أو تقصير المزود.',
