    'legal.termsContent4': '4. جميع النزاعات تخضع لقوانين بلد إقامة المستخدم. تلتزم المنصة بتسهيل حل النزاعات.',
    'legal.privacyTitle': 'سياسة الخصوصية',
    'legal.privacyContent1': '1. نجمع الحد الأدنى من البيانات: الاسم، الهاتف، عنوان الخدمة، والموقع الجغرافي.',
    'legal.privacyContent2': '2. البيانات مشفرة (AES-256) ولا تُشارك مع أطراف ثالثة دون موافقتك، إلا بموجب القانون.',
