    'legal.termsTitle': 'Conditions d\'utilisation de BOLH',
    'legal.termsContent1': '1. BOLH agit en tant que plateforme intermédiaire entre clients et prestataires. La plateforme n\'est pas partie au contrat de travail.',
    'legal.termsContent2': '2. Le prestataire assume l\'entière responsabilité de la qualité des services. La plateforme n\'est pas responsable des actions ou inactions du prestataire.',
    'legal.termsContent3': '3. La commission de la plateforme est non remboursable et couvre les frais opérationnels, la mise en relation et le support technique.',
    'legal.termsContent4': '4. Tous les litiges sont régis par les lois du pays de résidence de l\'utilisateur. La plateforme s\'engage à faciliter la résolution des conflits.',
    'legal.privacyTitle': 'Politique de confidentialité',
    'legal.privacyContent1': '1. Nous collectons le minimum de données nécessaires : nom, téléphone, adresse de service et géolocalisation.',
    'legal.privacyContent2': '2. Les données sont stockées chiffrées (AES-256) et ne sont pas partagées avec des tiers sans votre consentement, sauf obligation légale.',
    'legal.privacyContent3': '3. Vous avez le droit de demander la suppression de toutes vos données personnelles à tout moment via la section Sécurité.',
    'legal.cancelTitle': 'Politique d\'annulation et de remboursement',
    'legal.cancelContent1': '1. Contrat instantané : annulation gratuite avant l\'arrivée du spécialiste. Après — remboursement de 50%.',
